/** @format */
/**
 * External dependencies
 */
import React, { Component, Fragment } from 'react';
import PropTypes from 'prop-types';
import page from 'page';
import { connect } from 'react-redux';
import { get } from 'lodash';
import { localize } from 'i18n-calypso';

/**
 * Internal dependencies
 */
import HelpButton from './help-button';
import JetpackConnectHappychatButton from './happychat-button';
import LoggedOutFormLinks from 'components/logged-out-form/links';
import Placeholder from './plans-placeholder';
import PlansGrid from './plans-grid';
import PlansSkipButton from './plans-skip-button';
import QueryPlans from 'components/data/query-plans';
import QuerySitePlans from 'components/data/query-site-plans';
import { addItem } from 'lib/upgrades/actions';
import { clearPlan, isCalypsoStartedConnection, retrievePlan } from './persistence-utils';
import { completeFlow } from 'state/jetpack-connect/actions';
import { externalRedirect } from 'lib/route/path';
import { getCurrentUser } from 'state/current-user/selectors';
import { getPlanBySlug } from 'state/plans/selectors';
import { getSelectedSite } from 'state/ui/selectors';
import { isCurrentPlanPaid, isJetpackSite } from 'state/sites/selectors';
import { mc } from 'lib/analytics';
import { PLAN_JETPACK_FREE } from 'lib/plans/constants';
import { recordTracksEvent } from 'state/analytics/actions';
import {
	canCurrentUser,
	hasInitializedSites,
	isRtl,
	isSiteAutomatedTransfer,
} from 'state/selectors';

const CALYPSO_PLANS_PAGE = '/plans/';
const CALYPSO_REDIRECTION_PAGE = '/posts/';
const JETPACK_ADMIN_PATH = '/wp-admin/admin.php?page=jetpack';

class Plans extends Component {
	static propTypes = {
		queryRedirect: PropTypes.string,

		// Connected props
		hasPlan: PropTypes.bool, // null indicates unknown
		isAutomatedTransfer: PropTypes.bool, // null indicates unknown
	};

	redirecting = false;

	componentDidMount() {
		this.maybeRedirect();
		if ( ! this.redirecting ) {
			this.props.recordTracksEvent( 'calypso_jpc_plans_view', {
				user: this.props.userId,
			} );
		}
	}

	componentDidUpdate() {
		if ( ! this.redirecting ) {
			this.maybeRedirect();
		}
	}

	maybeRedirect() {
		if ( this.props.isAutomatedTransfer ) {
			externalRedirect( this.props.selectedSite.URL + JETPACK_ADMIN_PATH );
		}
		if ( this.props.selectedPlan ) {
			this.selectPlan( this.props.selectedPlan );
		}
		if ( this.props.hasPlan || this.props.notJetpack ) {
			this.redirect( CALYPSO_PLANS_PAGE );
		}
		if ( ! this.props.selectedSite && this.props.isSitesInitialized ) {
			// Invalid site
			this.redirect( '/jetpack/connect/plans' );
		}
		if ( ! this.props.canPurchasePlans ) {
			if ( this.props.calypsoStartedConnection ) {
				this.redirect( CALYPSO_REDIRECTION_PAGE );
			} else {
				this.redirectToWpAdmin();
			}
		}
	}

	handleSkipButtonClick = () => {
		this.props.recordTracksEvent( 'calypso_jpc_plans_skip_button_click' );

		this.selectFreeJetpackPlan();
	};

	handleHelpButtonClick = () => {
		this.props.recordTracksEvent( 'calypso_jpc_help_link_click' );
	};

	redirectToWpAdmin() {
		const { queryRedirect } = this.props;
		if ( queryRedirect ) {
			externalRedirect( queryRedirect );
			this.redirecting = true;
			this.props.completeFlow();
		} else if ( this.props.selectedSite ) {
			externalRedirect( this.props.selectedSite.URL + JETPACK_ADMIN_PATH );
			this.redirecting = true;
			this.props.completeFlow();
		}
	}

	redirect( path ) {
		page.redirect( path + this.props.selectedSiteSlug );
		this.redirecting = true;
		this.props.completeFlow();
	}

	selectFreeJetpackPlan() {
		clearPlan();
		this.props.recordTracksEvent( 'calypso_jpc_plans_submit_free', {
			user: this.props.userId,
		} );
		mc.bumpStat( 'calypso_jpc_plan_selection', 'jetpack_free' );

		if ( this.props.calypsoStartedConnection ) {
			this.redirect( CALYPSO_REDIRECTION_PAGE );
		} else {
			this.redirectToWpAdmin();
		}
	}

	selectPlan = cartItem => {
		clearPlan();

		if ( ! cartItem || cartItem.product_slug === PLAN_JETPACK_FREE ) {
			return this.selectFreeJetpackPlan();
		}

		if ( cartItem.product_slug === get( this.props, 'selectedSite.plan.product_slug', null ) ) {
			return this.redirect( CALYPSO_PLANS_PAGE );
		}

		this.props.recordTracksEvent( 'calypso_jpc_plans_submit', {
			user: this.props.userId,
			product_slug: cartItem.product_slug,
		} );
		mc.bumpStat( 'calypso_jpc_plan_selection', cartItem.product_slug );

		addItem( cartItem );
		this.props.completeFlow();
		this.redirect( '/checkout/' );
	};

	shouldShowPlaceholder() {
		return (
			this.redirecting ||
			this.props.selectedPlanSlug ||
			false !== this.props.notJetpack ||
			! this.props.canPurchasePlans ||
			false !== this.props.hasPlan ||
			false !== this.props.isAutomatedTransfer
		);
	}

	render() {
		const { interval, isRtlLayout, selectedSite, translate } = this.props;

		if ( this.shouldShowPlaceholder() ) {
			return (
				<Fragment>
					<QueryPlans />
					<Placeholder />
				</Fragment>
			);
		}

		const helpButtonLabel = translate( 'Need help?' );

		return (
			<Fragment>
				<QueryPlans />
				{ selectedSite && <QuerySitePlans siteId={ selectedSite.ID } /> }
				<PlansGrid
					basePlansPath={ '/jetpack/connect/plans' }
					onSelect={ this.selectPlan }
					hideFreePlan={ true }
					isLanding={ false }
					interval={ interval }
					selectedSite={ selectedSite }
				>
					<PlansSkipButton onClick={ this.handleSkipButtonClick } isRtl={ isRtlLayout } />
					<LoggedOutFormLinks>
						<JetpackConnectHappychatButton
							label={ helpButtonLabel }
							eventName="calypso_jpc_plans_chat_initiated"
						>
							<HelpButton onClick={ this.handleHelpButtonClick } label={ helpButtonLabel } />
						</JetpackConnectHappychatButton>
					</LoggedOutFormLinks>
				</PlansGrid>
			</Fragment>
		);
	}
}

export { Plans as PlansTestComponent };

export default connect(
	state => {
		const user = getCurrentUser( state );
		const selectedSite = getSelectedSite( state );
		const selectedSiteSlug = selectedSite ? selectedSite.slug : '';

		const selectedPlanSlug = retrievePlan();
		const selectedPlan = getPlanBySlug( state, selectedPlanSlug );

		return {
			calypsoStartedConnection: isCalypsoStartedConnection( selectedSiteSlug ),
			canPurchasePlans: selectedSite
				? canCurrentUser( state, selectedSite.ID, 'manage_options' )
				: true,
			hasPlan: selectedSite ? isCurrentPlanPaid( state, selectedSite.ID ) : null,
			isAutomatedTransfer: selectedSite ? isSiteAutomatedTransfer( state, selectedSite.ID ) : null,
			isRtlLayout: isRtl( state ),
			isSitesInitialized: hasInitializedSites( state ),
			notJetpack: selectedSite ? ! isJetpackSite( state, selectedSite.ID ) : null,
			selectedPlan,
			selectedPlanSlug,
			selectedSite,
			selectedSiteSlug,
			userId: user ? user.ID : null,
		};
	},
	{
		completeFlow,
		recordTracksEvent,
	}
)( localize( Plans ) );

/** @format */
/**
 * External Dependencies
 */
import React from 'react';
import Debug from 'debug';
import page from 'page';
import validator from 'is-my-json-valid';
import { get, isEmpty, some } from 'lodash';
import { translate } from 'i18n-calypso';

/**
 * Internal Dependencies
 */
import analytics from 'lib/analytics';
import CheckoutData from 'components/data/checkout';
import config from 'config';
import i18nUtils from 'lib/i18n-utils';
import JetpackAuthorize from './authorize';
import JetpackConnect from './main';
import JetpackNewSite from './jetpack-new-site/index';
import JetpackSignup from './signup';
import JetpackSsoForm from './sso';
import NoDirectAccessError from './no-direct-access-error';
import Plans from './plans';
import PlansLanding from './plans-landing';
import { sectionify } from 'lib/route';
import userFactory from 'lib/user';
import { authorizeQueryDataSchema } from './schema';
import { authQueryTransformer } from './utils';
import { JETPACK_CONNECT_QUERY_SET } from 'state/action-types';
import { MOBILE_APP_REDIRECT_URL_WHITELIST } from './constants';
import { receiveJetpackOnboardingCredentials } from 'state/jetpack-onboarding/actions';
import { setDocumentHeadTitle as setTitle } from 'state/document-head/actions';
import { setSection } from 'state/ui/actions';
import { persistMobileRedirect, storePlan } from './persistence-utils';
import { urlToSlug } from 'lib/url';
import {
	PLAN_JETPACK_PREMIUM,
	PLAN_JETPACK_PERSONAL,
	PLAN_JETPACK_BUSINESS,
	PLAN_JETPACK_PREMIUM_MONTHLY,
	PLAN_JETPACK_PERSONAL_MONTHLY,
	PLAN_JETPACK_BUSINESS_MONTHLY,
} from 'lib/plans/constants';

/**
 * Module variables
 */
const debug = new Debug( 'calypso:jetpack-connect:controller' );
const userModule = userFactory();
const analyticsPageTitleByType = {
	install: 'Jetpack Install',
	personal: 'Jetpack Connect Personal',
	premium: 'Jetpack Connect Premium',
	pro: 'Jetpack Install Pro',
};

const removeSidebar = context => {
	context.store.dispatch(
		setSection(
			{ name: 'jetpackConnect' },
			{
				hasSidebar: false,
			}
		)
	);
};

const jetpackNewSiteSelector = context => {
	removeSidebar( context );
	context.primary = React.createElement( JetpackNewSite, {
		path: context.path,
		context: context,
		locale: context.params.locale,
	} );
};

const getPlanSlugFromFlowType = ( type, interval = 'yearly' ) => {
	const planSlugs = {
		yearly: {
			personal: PLAN_JETPACK_PERSONAL,
			premium: PLAN_JETPACK_PREMIUM,
			pro: PLAN_JETPACK_BUSINESS,
		},
		monthly: {
			personal: PLAN_JETPACK_PERSONAL_MONTHLY,
			premium: PLAN_JETPACK_PREMIUM_MONTHLY,
			pro: PLAN_JETPACK_BUSINESS_MONTHLY,
		},
	};

	return get( planSlugs, [ interval, type ], '' );
};

export function redirectWithoutLocaleIfLoggedIn( context, next ) {
	if ( userModule.get() && i18nUtils.getLocaleFromPath( context.path ) ) {
		const urlWithoutLocale = i18nUtils.removeLocaleFromPath( context.path );
		debug( 'redirectWithoutLocaleIfLoggedIn to %s', urlWithoutLocale );
		return page.redirect( urlWithoutLocale );
	}

	next();
}

export function maybeOnboard( { query, store }, next ) {
	if ( ! isEmpty( query ) && query.onboarding ) {
		const siteId = parseInt( query.client_id, 10 );
		const siteSlug = urlToSlug( query.site_url );
		const credentials = {
			token: query.onboarding,
			siteUrl: query.site_url,
			userEmail: query.user_email,
		};

		store.dispatch( receiveJetpackOnboardingCredentials( siteId, credentials ) );

		return page.redirect( '/jetpack/onboarding/' + siteSlug );
	}

	next();
}

export function newSite( context, next ) {
	analytics.pageView.record( '/jetpack/new', 'Add a new site (Jetpack)' );
	jetpackNewSiteSelector( context );
	next();
}

export function connect( context, next ) {
	const { path, pathname, params, query } = context;
	const { type = false, interval } = params;
	const analyticsPageTitle = get( type, analyticsPageTitleByType, 'Jetpack Connect' );

	debug( 'entered connect flow with params %o', params );

	const planSlug = getPlanSlugFromFlowType( type, interval );
	planSlug && storePlan( planSlug );

	if ( config.isEnabled( 'jetpack/connect/mobile-app-flow' ) ) {
		if (
			some( MOBILE_APP_REDIRECT_URL_WHITELIST, pattern => pattern.test( query.mobile_redirect ) )
		) {
			debug( `In mobile app flow with redirect url: ${ query.mobile_redirect }` );
			persistMobileRedirect( query.mobile_redirect );
		} else {
			persistMobileRedirect( '' );
		}
	}

	analytics.pageView.record( pathname, analyticsPageTitle );

	removeSidebar( context );

	userModule.fetch();

	context.primary = React.createElement( JetpackConnect, {
		context,
		locale: params.locale,
		path,
		type,
		url: query.url,
		userModule,
	} );
	next();
}

export function signupForm( context, next ) {
	analytics.pageView.record( 'jetpack/connect/authorize', 'Jetpack Authorize' );

	removeSidebar( context );

	const { query } = context;
	const validQueryObject = validator( authorizeQueryDataSchema )( query );

	if ( validQueryObject ) {
		const transformedQuery = authQueryTransformer( query );

		// No longer setting/persisting query
		//
		// FIXME
		//
		// However, clientId is required for some reducer logic :(
		//
		// Set timestamp here so reducer can remain pure
		//
		// Hopefully when actions move to data-layer, this will become clearer and
		// we won't need to store clientId in state
		//
		context.store.dispatch( {
			type: JETPACK_CONNECT_QUERY_SET,
			clientId: transformedQuery.clientId,
			timestamp: Date.now(),
		} );

		let interval = context.params.interval;
		let locale = context.params.locale;
		if ( context.params.localeOrInterval ) {
			if ( [ 'monthly', 'yearly' ].indexOf( context.params.localeOrInterval ) >= 0 ) {
				interval = context.params.localeOrInterval;
			} else {
				locale = context.params.localeOrInterval;
			}
		}
		context.primary = (
			<JetpackSignup
				path={ context.path }
				interval={ interval }
				locale={ locale }
				authQuery={ transformedQuery }
			/>
		);
	} else {
		context.primary = <NoDirectAccessError />;
	}
	next();
}

export function authorizeForm( context, next ) {
	analytics.pageView.record( 'jetpack/connect/authorize', 'Jetpack Authorize' );

	removeSidebar( context );

	const { query } = context;
	const validQueryObject = validator( authorizeQueryDataSchema )( query );

	if ( validQueryObject ) {
		const transformedQuery = authQueryTransformer( query );

		// No longer setting/persisting query
		//
		// FIXME
		//
		// However, from and clientId are required for some reducer logic :(
		//
		// Hopefully when actions move to data-layer, this will become clearer and
		// we won't need to store clientId in state
		//
		context.store.dispatch( {
			type: JETPACK_CONNECT_QUERY_SET,
			clientId: transformedQuery.clientId,
			timestamp: Date.now(),
		} );

		context.primary = <JetpackAuthorize authQuery={ transformedQuery } />;
	} else {
		context.primary = <NoDirectAccessError />;
	}
	next();
}

export function sso( context, next ) {
	const analyticsBasePath = '/jetpack/sso';
	const analyticsPageTitle = 'Jetpack SSO';

	removeSidebar( context );

	userModule.fetch();

	analytics.pageView.record( analyticsBasePath, analyticsPageTitle );

	context.primary = React.createElement( JetpackSsoForm, {
		path: context.path,
		locale: context.params.locale,
		userModule: userModule,
		siteId: context.params.siteId,
		ssoNonce: context.params.ssoNonce,
	} );
	next();
}

export function plansLanding( context, next ) {
	const analyticsPageTitle = 'Plans';
	const basePath = sectionify( context.path );
	const analyticsBasePath = basePath + '/:site';

	removeSidebar( context );

	context.store.dispatch( setTitle( translate( 'Plans', { textOnly: true } ) ) );

	analytics.tracks.recordEvent( 'calypso_plans_view' );
	analytics.pageView.record( analyticsBasePath, analyticsPageTitle );

	context.primary = (
		<PlansLanding
			context={ context }
			destinationType={ context.params.destinationType }
			interval={ context.params.interval }
			basePlansPath={ '/jetpack/connect/store' }
			url={ context.query.site }
		/>
	);
	next();
}

export function plansSelection( context, next ) {
	const analyticsPageTitle = 'Plans';
	const basePath = sectionify( context.path );
	const analyticsBasePath = basePath + '/:site';

	removeSidebar( context );

	// FIXME: Auto-converted from the Flux setTitle action. Please use <DocumentHead> instead.
	context.store.dispatch( setTitle( translate( 'Plans', { textOnly: true } ) ) );

	analytics.tracks.recordEvent( 'calypso_plans_view' );
	analytics.pageView.record( analyticsBasePath, analyticsPageTitle );

	context.primary = (
		<CheckoutData>
			<Plans
				basePlansPath={ '/jetpack/connect/plans' }
				context={ context }
				destinationType={ context.params.destinationType }
				interval={ context.params.interval }
				queryRedirect={ context.query.redirect }
			/>
		</CheckoutData>
	);
	next();
}

/**
 * @format
 * @jest-environment jsdom
 */
/**
 * External dependencies
 */
import { shallow } from 'enzyme';
import React from 'react';

/**
 * Internal dependencies
 */
import PlansGrid from '../plans-grid';
import QueryPlans from 'components/data/query-plans';
import { DEFAULT_PROPS, SELECTED_SITE, SITE_PLAN_PRO } from './lib/plans';
import { PlansTestComponent as Plans } from '../plans';
import * as path from 'lib/route/path';

jest.mock( 'lib/route/path', () => ( {
	externalRedirect: jest.fn(),
} ) );

describe( 'Plans', () => {
	beforeEach( () => {
		path.externalRedirect.mockReset();
	} );
	test( 'should render plans', () => {
		const wrapper = shallow( <Plans { ...DEFAULT_PROPS } /> );

		expect( wrapper ).toMatchSnapshot();
		expect( wrapper.find( PlansGrid ) ).toHaveLength( 1 );
		expect( wrapper.find( QueryPlans ) ).toHaveLength( 1 );
	} );

	test( 'should render placeholder when shouldShowPlaceholder is true', () => {
		const wrapper = shallow( <Plans { ...DEFAULT_PROPS } /> );
		wrapper.instance().shouldShowPlaceholder = jest.fn( () => true );

		// Force rerender with our mocked method
		wrapper.setProps( DEFAULT_PROPS );

		expect( wrapper ).toMatchSnapshot();
		expect( wrapper.find( PlansGrid ) ).toHaveLength( 0 );
		expect( wrapper.find( QueryPlans ) ).toHaveLength( 1 );
	} );

	describe( 'shouldRenderPlaceholder', () => {
		test( 'should return true with unknown plan', () => {
			const wrapper = shallow( <Plans { ...DEFAULT_PROPS } hasPlan={ null } /> );

			expect( wrapper.instance().shouldShowPlaceholder() ).toBe( true );
		} );

		test( 'should return true if isAutomatedTransfer is null', () => {
			const wrapper = shallow( <Plans { ...DEFAULT_PROPS } isAutomatedTransfer={ null } /> );

			expect( wrapper.instance().shouldShowPlaceholder() ).toBe( true );
		} );

		test( 'should return true with a paid plan', () => {
			const wrapper = shallow(
				<Plans
					{ ...DEFAULT_PROPS }
					hasPlan={ true }
					selectedSite={ { ...SELECTED_SITE, plan: SITE_PLAN_PRO } }
				/>
			);

			expect( wrapper.instance().shouldShowPlaceholder() ).toBe( true );
		} );
	} );

	test( 'should redirect when hasPlan is loaded', () => {
		const wrapper = shallow(
			<Plans { ...DEFAULT_PROPS } hasPlan={ null } selectedSite={ null } />
		);

		const redirect = ( wrapper.instance().redirect = jest.fn() );

		wrapper.setProps( {
			hasPlan: true,
			selectedSite: { ...SELECTED_SITE, plan: SITE_PLAN_PRO },
		} );

		expect( redirect ).toHaveBeenCalledTimes( 1 );
	} );

	test( 'should redirect if notJetpack', () => {
		const wrapper = shallow(
			<Plans { ...DEFAULT_PROPS } hasPlan={ null } selectedSite={ null } notJetpack={ null } />
		);

		const redirect = ( wrapper.instance().redirect = jest.fn() );

		wrapper.setProps( {
			notJetpack: true,
			selectedSite: { ...SELECTED_SITE, plan: SITE_PLAN_PRO },
		} );

		expect( redirect ).toHaveBeenCalledTimes( 1 );
	} );

	test( 'should redirect if Atomic', () => {
		shallow(
			<Plans
				{ ...DEFAULT_PROPS }
				hasPlan={ true }
				isAutomatedTransfer={ true }
				selectedSite={ {
					...SELECTED_SITE,
					plan: SITE_PLAN_PRO,
					is_automated_transfer: true,
				} }
			/>
		);

		expect( path.externalRedirect ).toHaveBeenCalledTimes( 1 );
	} );
} );

